import java.util.*; class Main{static class Book{int id;String title;boolean available=true;Book(int i,String t){id=i;title=t;}}public static void main(String[]a){Scanner s=new Scanner(System.in);List<Book>b=new ArrayList<>();while(true){System.out.print("1 Add 2 List 3 Toggle 4 Exit: ");int c=s.nextInt();if(c==1)b.add(new Book(s.nextInt(),s.next()));else if(c==2)for(Book x:b)System.out.println(x.id+" "+x.title+" "+x.available);else if(c==3){int id=s.nextInt();for(Book x:b)if(x.id==id)x.available=!x.available;}else break;}}}